/**
 * RocketChat Node - Version 1
 * Discriminator: resource=dm, operation=messages
 */


interface Credentials {
  rocketchatApi: CredentialReference;
}

/** Retrieve a list of messages */
export type RocketchatV1DmMessagesParams = {
  resource: 'dm';
  operation: 'messages';
/**
 * The room identifier
 */
    roomId: string | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
};

export type RocketchatV1DmMessagesNode = {
  type: 'n8n-nodes-base.rocketchat';
  version: 1;
  config: NodeConfig<RocketchatV1DmMessagesParams> & { credentials?: Credentials };
};